import { NextRequest, NextResponse } from "next/server";
import { requireAuth } from "@/lib/server/auth";

/**
 * Online collection intentionally fails closed until the app persists the
 * gateway order/invoice relationship and verifies signed webhooks. In particular,
 * do not return a QR generated by the custom encoder or create a gateway order
 * whose amount and settlement cannot be reconciled server-side.
 */
export async function POST(req: NextRequest) {
  const access = requireAuth(req, ["ADMIN", "SALES", "ACCOUNTS"]);
  if ("errorResponse" in access) return access.errorResponse;

  return NextResponse.json(
    {
      success: false,
      code: "PAYMENT_COLLECTION_NOT_READY",
      error: "Online payment collection is temporarily unavailable. Use the authorised Accounts process to reconcile bank receipts until verified gateway reconciliation is enabled.",
    },
    { status: 503 }
  );
}
